function useReveal() {
  const ref = useRef(null);
  const [vis, setVis] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setVis(true); obs.unobserve(el); } }, { threshold: 0.12 });
    obs.observe(el); return () => obs.disconnect();
  }, []);
  return [ref, vis];
}
function Reveal({ children, delay = 0, style = {} }) {
  const [ref, vis] = useReveal();
  return <div ref={ref} style={{ opacity: vis ? 1 : 0, transform: vis ? "translateY(0)" : "translateY(28px)", transition: `opacity 0.65s ease ${delay}s, transform 0.65s ease ${delay}s`, ...style }}>{children}</div>;
}
function SectionHeader({ label, num, title }) {
  return (
    <Reveal>
      <p style={{ fontFamily: F.mono, fontSize: "0.72rem", color: C.copper, letterSpacing: "0.2em", textTransform: "uppercase", marginBottom: "10px" }}>{num} — {label}</p>
      <h2 style={{ fontFamily: F.display, fontSize: "clamp(1.8rem, 4vw, 2.8rem)", color: C.cream, marginBottom: "44px", fontWeight: 700 }}>{title}</h2>
    </Reveal>
  );
}

