// PORTFOLIO PAGE
// ═══════════════════════════════════════════════════════════════
function PortfolioPage() {
  const [hov, setHov] = useState(null);

  const akshardhamImages = [
    { url: "data:image/jpeg;base64,", alt: "BAPS Akshardham aerial view at dusk" },
    { url: "data:image/jpeg;base64,", alt: "BAPS Akshardham sunset with statue" },
  ];

  return (
    <div style={{ paddingTop: 80 }}>
      <section style={{ padding: "100px 32px", maxWidth: 920, margin: "0 auto" }}>
        <SectionHeader label="Portfolio" num="01" title="Selected work" />
        <div style={{ display: "flex", flexDirection: "column", gap: 22 }}>
          {SITE_CONFIG.projects.map((proj, i) => (
            <Reveal key={i} delay={i * 0.1}>
              <div onMouseEnter={() => setHov(i)} onMouseLeave={() => setHov(null)}
                style={{ padding: 34, background: hov === i ? C.navyMid : C.navyLight, borderRadius: 8, border: `1px solid ${hov === i ? C.copper + "44" : C.navyMid}`, cursor: "default", transition: "all 0.35s", transform: hov === i ? "translateY(-2px)" : "none", borderLeft: proj.highlight ? `4px solid ${C.copper}` : undefined }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10, flexWrap: "wrap", gap: 8 }}>
                  <h3 style={{ fontFamily: F.display, fontSize: "1.35rem", color: C.cream, fontWeight: 600 }}>{proj.title}</h3>
                  <span style={{ fontFamily: F.mono, fontSize: "0.62rem", color: C.copper, background: C.copperGlow, padding: "4px 12px", borderRadius: 18, letterSpacing: "0.08em", textTransform: "uppercase" }}>{proj.tag}</span>
                </div>
                <p style={{ fontFamily: F.body, fontSize: "0.93rem", color: C.slate, lineHeight: 1.7, marginBottom: 18 }}>{proj.description}</p>
                {proj.hasImages && (
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 18, borderRadius: 6, overflow: "hidden" }}>
                    {akshardhamImages.map((img, k) => (
                      <div key={k} style={{ height: 180, overflow: "hidden", borderRadius: 6, background: C.navy }}>
                        <img src={img.url} alt={img.alt}
                          style={{ width: "100%", height: "100%", objectFit: "cover", opacity: 0.9, transition: "opacity 0.3s" }}
                          onMouseEnter={e => e.target.style.opacity = 1}
                          onMouseLeave={e => e.target.style.opacity = 0.9}
                          onError={e => { e.target.style.display = "none"; }}
                        />
                      </div>
                    ))}
                  </div>
                )}
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                  {proj.tech.map((t, j) => <span key={j} style={{ fontFamily: F.mono, fontSize: "0.68rem", color: C.slate, padding: "4px 10px", border: `1px solid ${C.navyMid}`, borderRadius: 3 }}>{t}</span>)}
                </div>
              </div>
            </Reveal>
          ))}
        </div>
      </section>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// ARTICLES PAGE
// ═══════════════════════════════════════════════════════════════
function ArticlesPage() {
  const [hov, setHov] = useState(null);
  const [reading, setReading] = useState(null); // index of article being read

  if (reading !== null) {
    const post = SITE_CONFIG.blogPosts[reading];
    return (
      <div style={{ paddingTop: 80 }}>
        <section style={{ padding: "100px 32px", maxWidth: 720, margin: "0 auto" }}>
          <Reveal>
            <button onClick={() => { setReading(null); window.scrollTo(0, 0); }}
              style={{ background: "none", border: "none", color: C.copper, fontFamily: F.mono, fontSize: "0.78rem", cursor: "pointer", marginBottom: 32, letterSpacing: "0.08em", display: "flex", alignItems: "center", gap: 6 }}>
              ← Back to Articles
            </button>
          </Reveal>
          <Reveal delay={0.05}>
            <div style={{ marginBottom: 12, display: "flex", gap: 14 }}>
              <span style={{ fontFamily: F.mono, fontSize: "0.7rem", color: C.copper }}>{post.date}</span>
              <span style={{ fontFamily: F.mono, fontSize: "0.7rem", color: C.slate }}>{post.readTime}</span>
            </div>
            <h1 style={{ fontFamily: F.display, fontSize: "clamp(1.6rem, 4vw, 2.4rem)", color: C.cream, fontWeight: 700, lineHeight: 1.25, marginBottom: 40 }}>{post.title}</h1>
          </Reveal>
          <div>
            {post.content.map((block, i) => (
              <Reveal key={i} delay={0.08 + i * 0.02}>
                {block.type === "paragraph" && (
                  <p style={{ fontFamily: F.body, fontSize: "1.02rem", color: C.slate, lineHeight: 1.85, marginBottom: 22 }}>{block.text}</p>
                )}
                {block.type === "heading" && (
                  <h3 style={{ fontFamily: F.display, fontSize: "1.3rem", color: C.cream, fontWeight: 600, marginTop: 40, marginBottom: 16 }}>{block.text}</h3>
                )}
                {block.type === "quote" && (
                  <blockquote style={{ borderLeft: `3px solid ${C.copper}`, padding: "16px 24px", margin: "28px 0", background: C.copperGlow, borderRadius: "0 6px 6px 0" }}>
                    <p style={{ fontFamily: F.display, fontSize: "1.08rem", color: C.cream, fontStyle: "italic", lineHeight: 1.6, marginBottom: block.attribution ? 8 : 0 }}>"{block.text}"</p>
                    {block.attribution && (
                      <p style={{ fontFamily: F.mono, fontSize: "0.72rem", color: C.copper }}>— {block.attribution}</p>
                    )}
                  </blockquote>
                )}
              </Reveal>
            ))}
          </div>
          <Reveal delay={0.3}>
            <div style={{ marginTop: 60, paddingTop: 28, borderTop: `1px solid ${C.navyMid}` }}>
              <button onClick={() => { setReading(null); window.scrollTo(0, 0); }}
                style={{ background: "none", border: "none", color: C.copper, fontFamily: F.mono, fontSize: "0.78rem", cursor: "pointer", letterSpacing: "0.08em" }}>
                ← Back to Articles
              </button>
            </div>
          </Reveal>
        </section>
      </div>
    );
  }

  return (
    <div style={{ paddingTop: 80 }}>
      <section style={{ padding: "100px 32px", maxWidth: 920, margin: "0 auto" }}>
        <SectionHeader label="Articles" num="01" title="Writing & thoughts" />
        <div style={{ display: "flex", flexDirection: "column" }}>
          {SITE_CONFIG.blogPosts.map((post, i) => (
            <Reveal key={i} delay={i * 0.08}>
              <div onMouseEnter={() => setHov(i)} onMouseLeave={() => setHov(null)}
                onClick={() => { if (post.published) { setReading(i); window.scrollTo(0, 0); } }}
                style={{ padding: "26px 0", borderBottom: `1px solid ${C.navyMid}`, cursor: post.published ? "pointer" : "default" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 8, flexWrap: "wrap", gap: 8 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <h3 style={{ fontFamily: F.display, fontSize: "1.18rem", color: hov === i ? C.copper : C.cream, fontWeight: 600, transition: "color 0.3s" }}>{post.title}</h3>
                    {post.published && <span style={{ fontFamily: F.mono, fontSize: "0.58rem", color: C.copper, background: C.copperGlow, padding: "2px 8px", borderRadius: 10, textTransform: "uppercase", letterSpacing: "0.06em" }}>Read</span>}
                  </div>
                  <div style={{ display: "flex", gap: 14 }}>
                    <span style={{ fontFamily: F.mono, fontSize: "0.68rem", color: C.slate }}>{post.readTime}</span>
                    <span style={{ fontFamily: F.mono, fontSize: "0.68rem", color: C.copper }}>{post.date}</span>
                  </div>
                </div>
                <p style={{ fontFamily: F.body, fontSize: "0.9rem", color: C.slate, lineHeight: 1.6 }}>{post.excerpt}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </section>
    </div>
  );
}

