// ═══════════════════════════════════════════════════════════════
// APP
// ═══════════════════════════════════════════════════════════════
export default function App() {
  const [page, setPage] = useState("Home");

  return (
    <div style={{ minHeight: "100vh", background: C.navy, color: C.cream, fontFamily: F.body, overflowX: "hidden" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700;800&family=DM+Sans:wght@300;400;500;600&family=JetBrains+Mono:wght@300;400;500&display=swap');
        *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
        html { scroll-behavior: smooth; }
        ::selection { background: ${C.copper}; color: ${C.navy}; }
        @keyframes scrollPulse { 0%, 100% { opacity: 0.3; transform: scaleY(1); } 50% { opacity: 0.8; transform: scaleY(1.2); } }
        @media (max-width: 768px) { .desktop-nav { display: none !important; } .mobile-menu-btn { display: block !important; } }
        @media (min-width: 769px) { .mobile-menu-btn { display: none !important; } }
        ::-webkit-scrollbar { width: 5px; }
        ::-webkit-scrollbar-track { background: ${C.navy}; }
        ::-webkit-scrollbar-thumb { background: ${C.navyMid}; border-radius: 3px; }
        ::-webkit-scrollbar-thumb:hover { background: ${C.copper}; }
        img { max-width: 100%; }
      `}</style>

      <Nav page={page} setPage={setPage} />
      {page === "Home" && <HomePage setPage={setPage} />}
      {page === "About" && <AboutPage />}
      {page === "Portfolio" && <PortfolioPage />}
      {page === "Articles" && <ArticlesPage />}
      {page === "Arena" && <FinanceArena />}
      {page === "Lab" && <EVMSModule />}
      {page === "Contact" && <ContactPage />}

      <footer style={{ padding: "36px 32px", borderTop: `1px solid ${C.navyMid}`, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 14 }}>
        <span style={{ fontFamily: F.mono, fontSize: "0.68rem", color: C.slate }}>© 2026 {SITE_CONFIG.name}</span>
        <span style={{ fontFamily: F.mono, fontSize: "0.68rem", color: C.slate }}>Built with intention.</span>
      </footer>
    </div>
  );
}
